        'bass' => 'Sings Mozart\'s bass line in Latin, mostly D and A, from a low G-sharp on "sanguine" up to B on "passum" and the first "in mortis".',
    ],
    'now-is-the-month-of-maying' => [
        'soprano' => 'Carries Morley\'s dancing tune, often up on its top D, on "playing", "his bonny lass" and the fa las, and down to the D an octave below in the fa las.',
        'alto' => 'Sings a tune of its own close under the soprano, mostly on G and F-sharp, reaching A only in the second half, on "his bonny", "grass" and its fa las.',
        'tenor' => 'Sings Morley\'s two tenor parts joined into one, mostly on D, up to F on "his" and down to E in the second half\'s fa las.',
        'bass' => 'Sings the foundation, mostly D and G, from a low G on "Now", "Maying", "When" and the fa las up to A on "bonny" and the "Fa" after "grass".',
    ],
    'asleep-in-the-deep' => [
        'soprano' => 'Holds soft chords on "oo" high above the bass\'s tune, mostly on C, with B-flat, D and A.',
        'alto' => 'Holds soft chords on "oo" in the middle, mostly on A and E, between a low A and a C.',
        'tenor' => 'Holds soft chords on "oo" close to the bass\'s tune, mostly on C, rising to F as the refrain begins.',
        'bass' => 'Carries Petrie\'s tune and all the words, from "Stormy the night" up to a high D on "lovers stand", the first "Sailor" and "Danger", and down to the low F of the last "Beware!".',
    ],
    'with-cat-like-tread' => [
        'soprano' => 'Carries the pirates\' tune, from "Come, friends, who plough the sea" to the loud "With cat-like tread", reaching its top E on "burglaree", "way" and the "we" of "we feel".',
        'alto' => 'Sings the pirates\' words under the tune, from a low G-sharp on "Truce", "navigation", "Take" and "station" up to A on "Upon", "prey", "steal" and "cautious".',
        'tenor' => 'Is a policeman: sings "Tarantara" and its "ra"s under the pirates, mostly on E and F-sharp, up to A near the end.',
        'bass' => 'Is a policeman too: sings "Tarantara" on Sullivan\'s bass line, mostly E, A and D, with B, under the pirates\' march.',
    ],
    'abide-with-me' => [
        'soprano' => 'Carries Monk\'s calm tune, from E-flat up to C on "falls" and "deepens", and back down to E-flat on the last "me".',
        'alto' => 'Sings the words close under the tune on just four notes, mostly E-flat and D, stepping through E natural to F under "comforts flee".',
        'tenor' => 'Sings the words in the middle of the chords, mostly on B-flat, from a low E-flat on "fast falls" and the "abide" of "Lord, with me abide" up to C on "Lord", "fail, and comforts" and the last "abide".',
        'bass' => 'Sings the bass line, mostly roots, on E-flat, B-flat and C above all, down to a low G on "fast" and "helpers", and up to A-flat on "Help".',
    ],
    'shall-we-gather' => [
        'soprano' => 'Carries Lowry\'s tune, cheerful and steady, up to its top E-flat on "gather at" and "saints at", and down to the low E-flat on each "God".',
        'alto' => 'Sings mostly in thirds under the tune, on E-flat, F, G and D, high with it on "Yes, we\'ll gather" and "Gather with the saints", and ends on a low G under the last "God".',
        'tenor' => 'Sings the words mostly on B-flat, rising to E-flat on "river", "forever" and "Gather with the", and sings "Yes, we\'ll gather" on C, a sixth under the alto.',
        'bass' => 'Sings the roots on just three notes, E-flat, B-flat and A-flat, high on A-flat for the chorus\'s "Yes, we\'ll gather" and "Gather with the saints".',
    ],
    'come-thou-fount' => [
        'soprano' => 'Carries the tune Nettleton, lilting in three, up to its top E-flat on "some", "flaming" and "above".',
        'alto' => 'Sings close under the tune, mostly on E-flat, and climbs with everyone to B-flat on "melodious" and "flaming".',
        'tenor' => 'Sings the words in the middle of the chords, mostly on B-flat, with G and A-flat, up to E-flat on "melodious" and "tongues above".',
        'bass' => 'Sings the roots, mostly E-flat and B-flat, up to A-flat on "heart", "songs", "melodious", "tongues" and "thy".',
    ],
    'nearer-my-god' => [
        'soprano' => 'Carries Mason\'s tune Bethany, calm and even, from the low D on "Nearer" and "That" up to its top E on "all" in "Still all my song" and on the "Nearer" that follows.',
        'alto' => 'Sings the words under the tune, mostly on D, with G, C and B, up to G for "Still all my song shall be, Nearer, my", and down to B on "Nearer", "That" and the last "thee".',
        'tenor' => 'Sings the words in the middle of the chords, mostly on G, between F-sharp and C.',
        'bass' => 'Sings mostly the roots, most often G, D and C, from the high G on the opening "Nearer" down to the low G on the last "thee".',
    ],
    'greensleeves' => [
        'soprano' => 'Carries the old tune, gentle and lilting, up to its top E on the refrain\'s first and third "Greensleeves", and down to C-sharp on "discourteously" and "delight".',
        'alto' => 'Sings the words beneath the tune, mostly on C-sharp and A, up to F-sharp on "Alas! my" and "I have".',
        'tenor' => 'Sings the words in the middle of the harmony, mostly on F-sharp, G-sharp and A, moving mostly by step.',
        'bass' => 'Sings Macfarren\'s bass line, mostly E, C-sharp and F-sharp, ending on the low F-sharp under the last "Greensleeves".',
    ],
    'jerusalem' => [
        'soprano' => 'Carries Parry\'s broad tune, from the low B on "green?" up to its top E on "Jerusalem".',
        'alto' => 'Sings the words under the tune, mostly on D, B and E, from a low G on "green?" up to A on "Lamb".',
        'tenor' => 'Sings the words in the middle of the harmony, mostly on G and A, from a low D on "England\'s mountains green?" and the "And" after it, up to D on "here".',
        'bass' => 'Follows the lowest notes of Parry\'s accompaniment, mostly G, B and D, down to a low F-sharp in several lines, among them "England\'s", "Lamb of" and "dark Satanic", and up to A on "Countenance Divine".',
    ],
    'lift-every-voice' => [
        'soprano' => 'Carries Rosamond Johnson\'s tune, broad and stately, up to its top E on "rise, High" and "sun, Of", and down to a low B in "full of the faith that the dark past has".',
        'alto' => 'Sings the words under the tune, mostly on B, E and D, and climbs to its top G-sharp, a sixth under the tune, on "rise, High" and "sun, Of".',
        'tenor' => 'Sings the words in the middle of the chords, mostly on G, A and B, up to D on "loud" and "till".',
        'bass' => 'Sings the bass line, mostly G, D and E, and holds a low G through both "Sing a song full of" lines.',
    ],
    'drunken-sailor' => [
        'soprano' => 'Is the shantyman: sings "What shall we do with a drunken sailor" alone, then leads the chorus, up to its top E on "sailor" and "rises".',
        'alto' => 'Rests through the verse and comes in on the chorus, "Hooray and up she rises", mostly on G and F-sharp, ending on a low G on "morning".',
        'tenor' => 'Comes in on the chorus in strong, simple chords, mostly on B and A, up to D on the third "up" and down to E on "morning".',
        'bass' => 'Comes in on the chorus, mostly on the roots, E and D, down to a low G on the third "rises".',
    ],
    'leave-her-johnny' => [
        'soprano' => 'Is the shantyman: sings each grumble alone, from "O the times are hard" to "a leaking ship and a harping crew", up to its top D on "times", "bread" and "leaking".',
        'alto' => 'Rests through each grumble and comes in on "Leave her, Johnny, leave her" and "It\'s time for us to leave her", mostly on B, up to D on "leave her" at the end of each "Leave her, Johnny, leave her", and on "leave" in "to leave her".',
        'tenor' => 'Comes in on the answers, mostly on a low E, rising to B at the end of each "Leave her, Johnny, leave her".',
        'bass' => 'Answers on the bass of Sharp\'s chords, mostly a low G and D, rising to the G an octave up at the end of each "Leave her, Johnny, leave her".',
    ],
    'caro-mio-ben' => [
        'soprano' => 'Sings the voice line in Italian, slow and tender, from a low D on the first "languisce" up to its top F on the first "Cessa".',
        'alto' => 'Hums Parisotti\'s harmony on "oo", mostly on E-flat, with D and F, holding through most of the tune\'s short breaths and breathing at its own chord changes.',
        'tenor' => 'Hums the middle of the harmony on "oo", mostly on B-flat, G and A-flat, taking most of its breaths apart from the alto\'s and the bass\'s, sharing only the breaks as the interlude starts, between sections and before the last "languisce il cor".',
        'bass' => 'Hums the bass of Parisotti\'s piano part on "oo", mostly B-flat and E-flat, down to a low F in the middle section.',
    ],
    'shorty-george-blues' => [
        'soprano' => 'Sings Thomas\'s blues tune through all five verses, mostly on G, moving between B-flat, its blue note, and B, from the top D, first on "I wrote", down to D an octave below.',
        'alto' => 'Hums the piano\'s chords on "oo", mostly on D, holding through most of the tune\'s breaths and breathing at its own chord changes.',
        'tenor' => 'Hums the middle of the chords on "oo", mostly on G, with B and A, taking most of its breaths apart from the alto\'s and the bass\'s, all three breathing together between verses and twice near the end.',
        'bass' => 'Sings the roots on "doo", mostly G, with D and C where the chord changes, under every verse.',
    ],
    'o-holy-night' => [
        'soprano' => 'Carries Adam\'s tune, slow and lilting, from a low C on "night" and "birth" up to its top E in "O night divine!".',
        'alto' => 'Sings quiet chords under the verse, mostly on E, and the choir\'s part in the refrain, up to G on "knees!", on the "O" of "O hear", and on "night" and "divine!" in "O night divine!".',
        'tenor' => 'Sings the middle of the chords, mostly on C and G, down to a low E in the verse, first on "night of the" and "birth", and up to D on the last "night".',
        'bass' => 'Sings the organ\'s lowest notes in the verse and the choir\'s bass in the refrain, mostly on C and G, down to a low G under "night of the dear Saviour\'s", "thrill of hope" and "yonder breaks a".',
    ],
    'deep-river' => [
        'soprano' => 'Rests through the first refrain while the alto has the tune, then floats the refrain above it, mostly on long notes, from a slow "Deep, deep river" to "want to cross over into campground"; in the verse it sings the tune with the alto, in unison, through "gospel feast", then takes the top line. Its highest note, a G, comes on "over" in the second refrain and on "promised" in the verse, its lowest, a D, on the last "river", and it sings G, E-flat or B-flat most of the time.',
        'alto' => 'Carries the tune, twice through the refrain, with its octave leap from "is" up to "over" in "my home is over Jordan", and shares it with the soprano in the verse up to "gospel feast". Its highest note, an E-flat, comes on "over" both times and on "gospel", its lowest, a B-flat, on "into" in the second refrain and on the last "river", and it sings E-flat, G or C most of the time.',
        'tenor' => 'Sings the words in the middle of Burleigh\'s chords, C, B-flat, E-flat or D most of the time, stepping down D, D-flat, C under "Jordan, Deep, deep river" in the first refrain; in the verse it sings "Want to go" while the soprano and alto sing "Oh, don\'t you want to go", then sings "to that gospel feast" with them. Its highest note, a G, comes once, on "all" in "where all is peace?", and its lowest, an F, on the last "river".',
        'bass' => 'Sings Burleigh\'s bass line, on E-flat nearly a third of the time and on E-flat, B-flat, G or A-flat most of it, from its lowest note, an F, on "over" in "cross over" in the first refrain and on "want to cross" in the second, up to its highest, a B-flat, once, on "all" in "where all is peace?". At the close it moves B-flat, B natural, C, B-flat, A-flat, B-flat, E-flat under "is peace? Oh, deep river".',
    ],
    'white-coral-bells' => [
        'soprano' => 'Starts the round alone and sings both verses twice, from its low B-flat on "Lilies" and "That" up to its top D on "our" in "deck our garden walk" and on "the" in "when the fairies sing".',
        'alto' => 'Sings the same tune at the same pitch, coming in four bars after the soprano: nothing new to learn.',
        'tenor' => 'Sings the same tune an octave lower, for lower voices, coming in four bars after the alto.',
        'bass' => 'Sings the same low tune as the tenor, coming in last, four bars after it, and finishing alone on "That could happen only when the fairies sing".',
    ],
    'londons-burning' => [
        'soprano' => 'Starts the round alone and sings it three times through, up to its top C on every "Fire!" and every "pour", and down to the C an octave below on every "London\'s".',
        'alto' => 'Sings the same tune at the same pitch, coming in two bars after the soprano, and stops with everyone on its last "Fire!".',
        'tenor' => 'Sings the same tune an octave lower, for lower voices, coming in two bars after the alto, and stops with everyone on "engines".',
        'bass' => 'Sings the same low tune as the tenor, coming in last, two bars after it, and stops with everyone on "burning".',
    ],
    'three-blind-mice' => [
        'soprano' => 'Starts the round alone and sings it twice through, down to its low C on every "mice" and up to its top C on "all ran", "farmer\'s", "cut off their", "carving", "ever you" and "sight".',
        'alto' => 'Sings the same tune at the same pitch, coming in four bars after the soprano: nothing new to learn.',
        'tenor' => 'Sings the same tune an octave lower, for lower voices, coming in four bars after the alto.',
        'bass' => 'Sings the same low tune as the tenor, coming in last, four bars after it, and finishing alone from "ever you see such a sight" to the last "As three blind mice".',
    ],
    'oh-how-lovely' => [
        'soprano' => 'Starts the round alone and sings it three times through, up to its top C on each "sweetly", and down to its low E-flat on "O", at the end of "lovely" and of each "evening", and for the whole "Ding, dong" line.',
        'alto' => 'Sings the same tune at the same pitch, coming in six bars after the soprano, just as it starts "When the bells are sweetly ringing".',
        'tenor' => 'Sings the same tune an octave lower, for lower voices, coming in six bars after the alto, as the soprano reaches "Ding, dong".',
        'bass' => 'Sings the same low tune as the tenor, coming in last, six bars after it, and finishing alone on the last "Ding, dong, ding, dong, ding, dong!".',
    ],
    'ezekiel-saw-the-wheel' => [
        'soprano' => 'Carries the tune, mostly on G and B, sings each verse\'s solo lines alone, from "Some go to church fo\' to sing an\' shout" to "He\'ll talk \'bout me an\' he\'ll talk \'bout you", starting them on its top E, on "Some", "Befo\'", "Let" and "He\'ll talk", and goes down to its low D on the first syllable of every "Ezekiel", on "An\' de" before "little wheel" and on the first "a" in "\'Tis a wheel in a wheel".',
        'alto' => 'Rests through the soprano\'s solo lines and answers "\'Way in de middle ob de air" with everyone, mostly on B and D, rising to its top E only in the refrain, on "in de" in "\'Way up in de middle", "run by" in "little wheel run by faith" and "by de" in "run by de grace".',
        'tenor' => 'Rests through the soprano\'s solo lines and joins every answer, most often on G, then D, up to its top C on "in de" in "\'Way up in de middle" and down to its low C on "run by" in "little wheel run by faith".',
        'bass' => 'Sings the bass line, mostly on a low G, rests through the soprano\'s solo lines, and rises to its top note, D, on every "\'Way in de middle ob de", on "middle ob de" after "\'Way up in de" and on "grace ob" in "by de grace ob God".',
    ],
    'every-time-i-feel-the-spirit' => [
        'soprano' => 'Carries the tune of the refrain, mostly on E-flat and C, across an octave, from its top E-flat on every "Ev\'ry" and "feel" in "Ev\'ry time I feel the Spirit" down to the E-flat below on every "heart" and "pray.", and rests while the alto sings the verses.',
        'alto' => 'Sings both verses alone, "Upon the mountain my Lord spoke" and "All around me looks so shine", on C, E-flat and G, with an F on "fire" and "all", and in the refrain sings with everyone, mostly on G and A-flat, up to A-flat on "time I feel the" and the start of "moving", and down to C on every "heart".',
        'tenor' => 'Sings the refrain on just two notes, mostly B-flat, rising to E-flat on every "time I feel the" and "moving", and rests while the alto sings the verses.',
        'bass' => 'Sings the refrain mostly on the roots, most often on E-flat, down to its low A-flat on every "time I", and rests while the alto sings the verses.',
    ],
    'were-you-there' => [
        'soprano' => 'Asks each verse\'s question alone, as "Were you there when they crucified my Lord?" in verse 1, holding its last word while the others echo, then sings the rest with everyone, mostly on G and B, up to its top E on "crucified", "nailed", "pierced" and "sun" in each verse\'s second question and on every "Sometimes", and down to its low D on each verse\'s first "Were" and its last "tremble,".',
        'alto' => 'Rests while the soprano asks each question, echoes her on B, C and B ("were you there?" in verses 1 and 4, "to the tree?" and "in the side?" in verses 2 and 3), then sings with everyone, mostly on B and E, reaching its top B only in each verse\'s second question, on every "Oh!" and on every "Sometimes".',
        'tenor' => 'Echoes each question with the alto and bass, then fills the middle of the chord, most often on G, then C, up to its top C on "me to tremble," and the second "tremble" in "Sometimes it causes me to tremble", and on "crucified", "nailed", "pierced" and "sun" in each verse\'s last line; its low C comes once a verse, in the echo, on "you" or "the".',
        'bass' => 'Echoes each question with the alto and tenor, then sings the bass line, most often on a low G, then C, rising to the G an octave up once a verse, in its last line, on "crucified", on "Him" in "nailed Him" and "pierced Him", and on "refused".',
    ],
    'didnt-my-lord-deliver-daniel' => [
        'soprano' => 'Sings the five-note tune, mostly on C and D, and each verse alone until the others join its last line, up to its top E on "Daniel," after each "Didn\'t my Lord deliver" or "d\'liver" and on "why" in the refrain, and on "belly", "fiery", "forbear", "disappear,", "begin" and "Canaan\'s" in the verses, and down to its low G on the start of each "deliver" or "d\'liver" after "Didn\'t my Lord".',
        'alto' => 'Sings the refrain and each verse\'s last line, mostly on C, a steady low line under the tune, up to its top E on the third "Daniel," of each refrain and on "why not", "Jesus" and "never come" in the verses\' last lines, and down to A on every "every" in the refrain\'s "And why not a every man?".',
        'tenor' => 'Sings the refrain and each verse\'s last line, most often on A, then G, and drops to its low E on "a" and "man?" in each "And why not a every man?", and in the verses on "And why not" and "man?", "King Jesus" and "mine.", and "And I\'ll never come" and "more.".',
        'bass' => 'Sings the roots, mostly on a low A, then C, joins each verse\'s last line on A, with G only on "every", "shall" and "back", and drops to its bottom F on "every" in each refrain\'s "And why not a every man?".',
    ],
    'balm-in-gilead' => [
        'soprano' => 'Carries the tune, mostly on A and C-sharp, and sings both verses alone, "Sometimes I feel discouraged" and "If you cannot preach like Peter", reaching its top E only there, on "discouraged,", "work\'s" and "Spirit" in the first and on "Peter,", "pray" and "Jesus," in the second, and down to its low E on every "To" in "To heal the sin-sick soul".',
        'alto' => 'Rests through both verses and sings Dett\'s alto in the refrain, mostly on C-sharp and E, up to F-sharp, its top note, on every "wounded" and "whole," and on the first "soul." of each refrain.',
        'tenor' => 'Rests through both verses and sings the refrain on just three notes, mostly on A, dropping to E on every "in Gilead,", on "Balm" before each "To make the wounded whole" and on the last "soul." of each refrain, and to G-sharp on every "whole,", the "There is a" after it and "sick" in every "sin-sick".',
        'bass' => 'Sings the roots of Dett\'s chords on just two notes, a low A for three quarters of the time and the E above it on every "whole,", the "There is a" after it and every "sin-sick", and rests through both verses.',
    ],
    'bully-in-the-alley' => [
        'soprano' => 'Is the shantyman: sings the opening refrain\'s two "So help my bob I\'m bully in the alley" lines alone, and in each verse its first line and "Bully in Tinpot alley", most often on G, then B and A, from its low D on every "So" up to its top D on every "I\'m", on "our" in the first lines of verses 1 and 2, on the second "the" in verse 3\'s "She\'s the girl in the alley." and on "in" in every "Bully in Tinpot alley".',
        'alto' => 'Answers "Way ay bully in the alley" with everyone and, in the verses, also sings "So help my bob I\'m bully in the alley", mostly on E, C and D, from a low A on each verse\'s "So" up to its top G on "ay" in both answers of the opening refrain and in each verse\'s last answer.',
        'tenor' => 'Answers with everyone, and in the verses sings "So help my bob I\'m bully in the alley" too, most often on G, up to its top D only once, on "ay" in the opening refrain\'s second "Way ay", and down to a low D on the last "alley." of each verse.',
        'bass' => 'Sings the bass line under the answers, mostly on C and a low G, and in the verses under "So help my bob I\'m bully in the alley" too, rising to its top E only once, on "ay" in the opening refrain\'s first "Way ay".',
    ],
    'haul-on-the-bowline' => [
        'soprano' => 'Is the shantyman: sings the whole chorus alone first, as his call, then each verse\'s first line alone, "Because she had a foretop" and "Because she had a maintop", starting each on its low D on "Because", most often on D, then B, up to its top E on the first "bowline," of the opening call and of the closing chorus.',
        'alto' => 'Rests through the shantyman\'s call and solo lines, joins each verse\'s last line ("Haul on the bowline, the bowline haul", in verse 2 "Haul the bowline") and sings the whole last chorus, mostly on F-sharp and G, up to its top A only there, on "bowline, O" in "Haul on the bowline, O Kitty".',
        'tenor' => 'Rests through the call and the solo lines, then sings each verse\'s last line and the last chorus, mostly on A and D, on its low F-sharp for "Haul on the" at the start of verse 1\'s answer, and up to its top E once, on the last "bowline" before the final "haul".',
        'bass' => 'Rests through the call and the solo lines, then sings the bass line, most often on B, then A and D, down to its low G once, on "darling," in the last chorus, and up to its top F-sharp on "bowline, the" in that chorus\'s last line.',
    ],
    'spanish-ladies' => [
        'soprano' => 'Carries Sharp\'s tune in its old minor form, mostly on A and C, up to its top E on "sail" and "But" in the verse and on "channel" and "From" in each chorus, and down to its low D on "to" in "short time to see you again" and on "is" in each "to Scilly is thirty five leagues".',
        'alto' => 'Sings the words with the tune all through, mostly on C and E, up to its top A only on "strike" in each "Until we strike soundings", and turns the last chord major with a C-sharp on the very last "leagues.".',
        'tenor' => 'Sings the words in the middle of the chord, mostly on E and G, staying on E for most of the opening "Farewell and adieu to you Spanish ladies", and up to its top D on "Until" in each chorus.',
        'bass' => 'Sings the bass line from Sharp\'s left hand, mostly on A and C, up to its top A only once, on "hope" in "But we hope in a short time", and down to its low F on "old" in every "old England", on "like" in "roar like true British sailors" and on "roar" in "we\'ll roar all on the salt seas".',
    ],
    'blow-boys-blow' => [
        'soprano' => 'Is the shantyman: sings both solo lines of every verse alone, among them "A Yankee ship came down the river" and "Why bullock\'s lights and donkey\'s liver.", mostly on B and G, starting each verse on its low D ("A", "And" or "Then") and each second solo line on its top E ("Her", "The", "Why" or "And").',
        'alto' => 'Rests through the solo lines and answers "Blow, boys blow." rising E, G-sharp, A, its top note, and "Blow my bully boys blow." falling G, F-sharp, D to a low B on the last "blow.", the same in every verse.',
        'tenor' => 'Rests through the solo lines and answers in the middle of the chord, mostly on G and A, starting "Blow, boys blow." on its top C in verse 1 and on its low E in every verse after.',
        'bass' => 'Rests through the solo lines and sings the bass of Terry\'s chords, C, E, A under "Blow, boys blow.", with its top E on "boys", then D for "Blow my bully boys" and down to a low G on the last "blow.", the same in every verse.',
    ],
    'maoz-tzur' => [
        'soprano' => 'Carries the traditional tune, most often on E, then B, dipping to its low B on "Maoz" and "Tikon" in verse 1 and on "Yevanim" and "Ufartzu" in verse 5, up to its top E on "matbeach," and "mitzar" in verse 1 and on "kankanim," and "naasa" in verse 5, and sings each verse\'s last line twice.',
        'alto' => 'Sings the words under the tune, mostly a third or a sixth below it, most often on G-sharp, up to its top B only on "mitzar" in verse 1 and "naasa" in verse 5, and crosses a third above the tune, to G-sharp, on the last note of every "hamizbeach." and "urenanim." and on "alai," and "migdalai," in verse 5.',
        'tenor' => 'Sings the middle of the chord, most often on B, then E, up to its top E only on "hamenabeach." in verse 1 and "nes" in verse 5, and down to its low D-sharp on "yeshuati,", "leshabeach.", "tefilati," and "nezabeach." in verse 1 and on "Chashmanim." and "hashemanim." in verse 5.',
        'bass' => 'Sings mostly the roots of the chords, on E just over half the time, then B, up to the higher A only on "hamenabeach." in verse 1 and "naasa" in verse 5, and down to the low A an octave under it on "nae", "toda", "tachin" and every "chanukat hamizbeach." in verse 1, and on "azai", "vetim\'u", "Uminotar" and every "kav\'u shir urenanim." in verse 5.',
    ],
    'oy-chanukah' => [
        'soprano' => 'Carries the Hasidic tune as the songbook prints it, quick and light, most often on C, then A-flat, up to its top F on the second "Khanike," and on "freylekher," each time verse 1 is sung and on "fartribn" and "hamikdesh" in verse 2, and down to its low F on, among others, the first and last words of every verse, "Oy," and "kon." in verse 1 and "Yehude" and "oykh." in verse 2.',
        'alto' => 'Sings the alto part printed under Lvov\'s name, with the words, mostly a third or a sixth below the tune, most often on A-flat, then F, up to its top B-flat on "likhtelekh" each time verse 1 is sung and on "hamakabi" in verse 2, and down to its low A-flat on the last word of every verse, "kon." and "oykh.".',
        'tenor' => 'Sings the words in the middle of the chord, taken from the piano left hand printed under Lvov\'s name, most often on C, then A-flat, up to its top E on "sheyner," and "azoyner." each time verse 1 is sung and on "rotseyekh," and "lamnatseyekh." in verse 2, and down to its low C on the last word of every verse, "kon." and "oykh.".',
        'bass' => 'Sings the bass line of the piano left hand printed under Lvov\'s name on "dm", a short note on the beat under the others, once or twice a bar, mostly on F, and joins the words only for the last word of each verse, "kon." and "oykh.", on its low F.',
    ],
    'oyfn-pripetchik' => [
        'soprano' => 'Carries Warshawsky\'s tune as Kisselgof\'s book prints it, most often on G and C, then A-flat and F, up to its top F on the "un" of "un der rebe" both times in verse 1, on the "vifl" of "vifl in di oysyes" both times in verse 2 and on "zogt" in both "zogt zhe nokh a mol" lines of each refrain, and down to its low C on the end of "kinderlekh," in each refrain.',
        'alto' => 'Sings the words from Lvov\'s two alto voices, mostly a sixth below the tune, sometimes a third, most often on F, then A-flat and E, up to its top A, an A natural, on the second "un der rebe" in verse 1, the second "vifl in di oysyes" in verse 2 and the second "zogt zhe nokh a mol" in each refrain, each time on its first word, and down to its low G on the end of "kinderlekh," in each refrain.',
        'tenor' => 'Sings the words in the middle of the chord, from Lvov\'s two alto voices an octave down, most often on C, then F and A-flat, up to its top D-flat on "un in" and both "lernt" in verse 1, "vet ir" and both "oysyes" in verse 2, and "vos ir" and both "mol un" in each refrain, and down to its low C on "beys." and "geveyn.", the last word of each verse, and on the song\'s last "o!".',
        'bass' => 'Sings the words on the bass line, from Lvov\'s piano left hand, most often on B-flat and its low F, then C and A-flat, up to its top F only at the start of each verse, on "Oyf dem pripetshik" and on "Az ir vet, kinderlekh," all but its last syllable.',
    ],
    'rozhinkes-mit-mandlen' => [
        'soprano' => 'Carries Goldfaden\'s lullaby with the words through the verse while the others hum, most often on B, then E and D, up to its top F-sharp only on "almone" and down to its low D on the end of "keseyder" and on "un zingt", and leads the refrain, singing "Unter" and "shteyt a" alone before the others come in.',
        'alto' => 'Hums the verse on "oo" with the others, mostly on F-sharp, G and B, up to its top B under "aleyn" and down to its low B, held from "yokhidl" into "keseyder", then sings the refrain\'s words under the tune, mostly a third or a sixth below and most often on G, humming again under "dos tsigele iz geforn".',
        'tenor' => 'Hums the verse on "oo", mostly on B, D and G, down to its low G, held from "yokhidl" into "keseyder" and again under "zingt im tsum", then sings the refrain\'s words in the middle of the chord, up to its top E for "Yideles vigele" and "klor vays tsigele", dipping a semitone on each "ge".',
        'bass' => 'Hums the roots of the chords under the verse on "oo", mostly on G and B, down to its low F-sharp only under "Tsiyon" and the start of "aleyn", then sings the refrain\'s words on the roots, mostly on E, its top note, which it takes on every E minor chord in the song.',
    ],
    'ein-keloheinu' => [
        'soprano' => 'Carries Freudenthal\'s tune, most often on G, then B, up to its top E on "kemalkenu," in verse 1, "lemalkenu," in verse 3 and "malkenu," in verse 5, and down to its low C-sharp only on "ch\'moshienu." in verse 2 and "moshienu." in verse 4.',
        'alto' => 'Sings under the tune, mostly a third or a sixth below it, most often on D, then G, from its low B on the opening "Ein", "Node" and "Ata hu" of verses 1, 3 and 5 up to its top B on "ein" before "kemalkenu,", "node" before "lemalkenu,", "ata hu" before "malkenu," and the last "moshienu.", where it ends a third above the tune.',
        'tenor' => 'Sings the middle of the chord, most often on A, staying on A for three quarters of verses 2 and 4, and up to its top E on "kemalkenu," in verse 1, "lemalkenu," in verse 3 and the last "ata" in verse 5.',
        'bass' => 'Sings the bass line, on the chords\' roots three quarters of the time, on G and D two thirds of the time, and goes down to its low A only in verses 2 and 4, on "mi chadoneinu," and "ch\'moshienu." and on "baruch adoneinu," and "moshienu.".',
    ],
    'adir-hu' => [
        'soprano' => 'Carries the traditional tune, most often on G, then C, up to its top E on "bimhera," and "veitcha" in every verse, and down to its low E on the names that open each verse ("Adir" and both "adir" in verse 1, "Bachur", "gadol" and "yachid" in verse 2, "Tzadik", "kadosh" and "rachum" in verse 3), and on "beyameinu", the "bekarov." after it and the first "bene," of every verse.',
        'alto' => 'Sings under the tune, a third or a sixth below it most of the time, mostly on E, up to its top A only on "bimhera," and down to its low B only on the "bekarov." after "beyameinu", in every verse.',
        'tenor' => 'Sings the middle of the chord on just five notes, mostly on G, up to C on the third "adir hu," in verse 1, on "yachid hu," and "rachum hu," in verses 2 and 3 and on every second "bimhera," and every "beyameinu", and down to F on the first "bekarov," and the "bekarov." after "beyameinu" in every verse.',
        'bass' => 'Sings mostly the roots of the chords, on a low C most of the time, staying on it under the names that open each verse, up to its top G only on "veito" and down to its low F only on the last "bekarov." of every verse.',
    ],
    'eliyahu-hanavi' => [
        'soprano' => 'Carries the folk tune Idelsohn printed, most often on G, then B-flat and D, down to its low D on "hanavi," and up to its top E-flat only on the last "Eliyahu", before "hagiladi.", the same each time through.',
        'alto' => 'Sings under the tune, mostly a third or a sixth below it, most often on E-flat, then D, down to its low A on "hanavi," and up to its top G on "hatishbi,", the first "Eliyahu," and the "Eliyahu" before "hagiladi.", the same each time through.',
        'tenor' => 'Sings the middle of the chord, most often on B-flat, then G, up to its top D on the first "Eliyahu," each time through, and down to its low D, an octave under it, only on the very last "hagiladi.".',
        'bass' => 'Sings the bass line, most often on G, then B-flat, from its low G on the first "Eliyahu", "hanavi," and "hagiladi." up to its top G, an octave higher, on the "Eliyahu" before "hatishbi,", the same each time through.',
    ],
    'echad-mi-yodea' => [
        'soprano' => 'Carries the traditional tune, most often on F, then C, up to its top D-flat on the first "yodea," and on "shebashamayim" in every verse, and down to its low E only on "uvaaretz.", the last word of every verse.',
        'alto' => 'Sings under the tune, mostly a sixth below it, most often on A-flat, then E-flat, up to its top F on "ani" in verses 1, 3 and 4, on the "shenayim" after "mi yodea," in verse 2 and on every "shebashamayim", and down to its low A-flat on the "Echad", "Shenayim", "Sh\'losha" and "Arba" that open the verses, on the "echad" before every "elokeinu" and on every "uvaaretz.".',
        'tenor' => 'Sings the middle of the chord, most often on A-flat, then F, up to its top B-flat on the first "yodea," in verses 1 and 4 and on every "imahot,", "avot," and "hab\'rit,", and down to its low C on every "uvaaretz.".',
        'bass' => 'Sings the bass line, most often on F, then C, up to its top F on "ani" in verse 2 and on the "yodea," after "ani" in verses 1, 3 and 4, and down to its low F, an octave under it, on the "Echad", "Shenayim", "Sh\'losha" and "Arba" that open the verses, on every "elokeinu" and on every "uvaaretz.".',
    ],
    'ki-lo-naeh' => [
        'soprano' => 'Carries the traditional tune and sings each verse alone, from "Adir bimlucha," to "yomru lo:" and the same lines of verses 2 and 3, most often on A, then F-sharp, up to its top D on every "yae." and on the first "lecha" and the "lecha" before "af" in every answer, and down to its low D on every "Ki" that opens "Ki lo nae,", on every "kahalacha," and on "gedudav", "shinanav" and "temimav".',
        'alto' => 'Rests while the soprano sings each verse alone and joins for "Ki lo nae, ki lo yae." and every answer, mostly a third or a sixth below the tune, most often on D, then C-sharp, up to its top F-sharp on every "yae." and, in every answer, on the first "lecha" and on "ki lecha," and "lecha af lecha,", and down to its low A only on the "Ki lo" that opens every "Ki lo nae,".',
        'tenor' => 'Rests while the soprano sings each verse alone and joins for "Ki lo nae, ki lo yae." and every answer in the middle of the chord, on F-sharp, G and A over nine tenths of the time, most often on F-sharp, up to its top C-sharp on the first "lecha" of every answer and down to its low D on every "nae,".',
        'bass' => 'Rests while the soprano sings each verse alone and joins for "Ki lo nae, ki lo yae." and every answer, singing the bass line, most often on D, then B, up to its top F-sharp on the "lecha" before "Adoshem" in every answer, and down to its low F-sharp, an octave under it, on every "nae," and the "ki" after it, and on "af", the "lecha," after it and "hamamlacha," in every answer.',
    ],
    'lecha-dodi' => [
        'soprano' => 'Carries the tune Francis L. Cohen printed for the weeks of the Omer, most often on G, then B, up to its top E on every "dodi", and down to its low D on every "penei", on "Shamor" and "Adoshem" in verse 1 and on the first "Boi" and "toch" in verse 9.',
        'alto' => 'Sings under the tune, mostly a third or a sixth below it, most often on E, then C, up to its top B on every "Lecha", on "velithila." at the end of verse 1 and on "chala!" at the end of verse 9, and down to its low B on every "penei" and "nekabela.", on "Shamor", both "echad,", "hishmianu", "hameyuchad." and "Adoshem" in verse 1, and on the first "Boi", "bala,", "gam", "uvetzahala,", "toch" and "segula." in verse 9.',
        'tenor' => 'Sings the middle of the chord, most often on G, then C, up to its top D on every "Lecha", and down to its low D, an octave under it, only on the very last "nekabela.".',
        'bass' => 'Sings the bass line, most often on C, then D, up to its top E on "bedibur", "hishmianu", "ushmo" and "ultiferet" in verse 1 and on "ateret", "gam", "am", "chala," and the "boi" after it in verse 9, and down to its low G on every "Lecha", "likrat", "Shabat" and "nekabela." and on the last word of every line of both verses: both "echad,", "hameyuchad." and "velithila." in verse 1, and "bala,", "uvetzahala,", "segula." and "chala!" in verse 9.',
    ],
    'tzur-mishelo' => [
        'soprano' => 'Carries the German melody Francis L. Cohen printed, most often on G, then A, up to its top F only on "lishmo" in verse 1 and "hanikdash" in verse 4, and down to its low D on every "emunai,", on "avinu," in verse 1 and on "temale," in verse 4.',
        'alto' => 'Sings under the tune, mostly a third or a sixth below it, most often on F, then B-flat, up to its top A on "lishmo" and "befinu," in verse 1 and on "hanikdash" and "veyitale" in verse 4, and down to its low A on every "Adoshem.", on "shatinu." and "kadoshem." in verse 1 and on "naale." in verse 4.',
        'tenor' => 'Sings the middle of the chord, most often on G, then C, up to its top C on "achalnu,", "vehotarnu" and "kidvar" in every refrain, on "lachmo,", "veyeino", "befinu," and every word from "amarnu" to "kadosh" in verse 1, and on "chadash", "uvirnana", "veyitale" and every word from "al" to "kevirkat" in verse 4, and down to its low D only on "naale." in verse 4.',
        'bass' => 'Sings the bass line, most often on B-flat, then G, up to its top E-flat on "barchu" and "emunai," in every refrain, on "roenu" and "avinu," in verse 1 and on "ir", "Tziyon" and "temale," in verse 4, and down to its low F on "achalnu," in every refrain, on "lishmo" and "befinu," in verse 1 and on "hanikdash" and "veyitale" in verse 4.',
    ],
    'adon-olam' => [
        'soprano' => 'Carries the old synagogue tune Gerovitsch printed, most often on A, then D, up to its top E on "b\'terem", "levado", "lehamshilo" and "ishan", once each time through, and down to its low D at the end of the first and last phrase each time through, on "malach,", "nikra.", "hakol,", "betifara.", "sheni", "vehamisra.", the first "ruchi" and "ira.".',
        'alto' => 'Sings under the tune, mostly a third or a sixth below it, most often on F, then E, up to its top A on the "kol" after "b\'terem", "levado", "lehamshilo" and "ishan", and down to its low C on "nivra.", "nora.", "lehachbira." and "veaira.", and rises a third above the tune, to F, where the tune falls to its low D, on "malach,", "nikra.", "hakol,", "betifara.", "sheni", "vehamisra.", the first "ruchi" and "ira.".',
        'tenor' => 'Sings the middle of the chord, most often on A, then C, up to its top D on the words that open each time through, "Adon olam", "Veacharei", "Vehu echad" and "Beyado", and down to its low F in the third phrase each time through, on "naasa" and "vecheftzo", "haya" and the "vehu" after it, "reshit" and the "beli" after it, and the second "ruchi" and "geviyati,".',
        'bass' => 'Sings the bass line, most often on D, then A, up to its top F on "b\'terem", "levado", "lehamshilo" and "b\'et", where the second phrase of each time through begins, and down to its low F, an octave under it, on "melech", "yihye", "haoz" and "li", in the last phrase each time through.',
    ],
    'shoshanat-yaakov' => [
        'soprano' => 'Carries the cantor\'s tune Abraham Baer printed, most often on F, then G, up to its top E-flat on "lo" and "yevoshu," both times through, and down to its low B-flat on "Yaakov" and "Teshuatam" both times through.',
        'alto' => 'Sings under the tune, mostly a third or a sixth below it, most often on D, then E-flat, up to its top B-flat only on "velo" both times through, and down to its low B-flat, an octave under it, on "Yaakov", "tzahala", "vesamecha" and "Teshuatam" both times through.',
        'tenor' => 'Sings the middle of the chord, most often on B-flat, then G, up to its top E-flat on "yevoshu,", "velo" and "yikalmu" both times through, and down to its low D only the first time through, on "Shoshanat", "Yaakov", "tzahala" and the start of "vesamecha".',
        'bass' => 'Sings the roots of the chords nearly all the time, most often on B-flat, then C, up to its top B-flat, an octave over the B-flat it starts on, only on "velo" both times through, and down to its low F on "bechol", "vador," and "hachosim" both times through and on "zachur" and "latov." in the soft last line.',
    ],
    'praise-to-the-lord' => [
        'soprano' => 'Carries the chorale tune, mostly by step, most often on G, then A, up to its top E only on "hear," in verse 1 and "seen" in verse 2, and down to its low D on "the" before "King", on "thy" and on "Join" in verse 1, and on both "so"s and on "Granted" in verse 2.',
        'alto' => 'Sings the words a third or a sixth under the tune nearly nine tenths of the time, mostly a third, moving mostly by step, most often on F-sharp, down to its low B on the first and last words of the first two lines of each verse, wherever the tune drops to its low D, and on the last word of each verse, and up to its top B on "All" and "who" in "All ye who hear," and on the start of "temple" in verse 1, and on "Hast" and "not" in "Hast thou not seen" in verse 2.',
        'tenor' => 'Sings the words in the middle of the chord, mostly a sixth under the tune, most often on B, then D and C, up to its top E only on "to" and the end of "temple" in "Now to His temple draw near," and on "thy" in "How thy desires have been", and down to its low D only on the end of the last word, "ordaineth?".',
        'bass' => 'Sings the roots of the chords most of the time, most often on G, then D, with many leaps of a fourth or a fifth, within one octave, singing the low G wherever the tune drops to its low D and on the last word of each verse.',
    ],
    'come-ye-thankful-people' => [
        'soprano' => 'Carries Elvey\'s tune, most often on B, up to its top E only in the last three lines of each verse, on "supplied;", "Come to" and the "the" of "Raise the song" in verse 1, and on "abide:", "Come, with" and the "the" of "Raise the glorious" in verse 4, and down to its low D only on the last word of the fourth line, "begin;" and "sin;".',
        'alto' => 'Sings the words under the tune, mostly a sixth below it, most often on D, up to its top G-sharp on "Come to" in verse 1 and "Come, with" in verse 4, and crosses a third above the tune, to F-sharp, where the tune drops to its low D, on "begin;" and "sin;".',
        'tenor' => 'Sings the words in the middle of the chord, mostly on G and A, with many repeated notes, up to its top E only on "to God\'s" in verse 1 and "with all" in verse 4, and down to its low D only on the last note of each verse, the "Home!" of "Harvest-Home!" in verse 1 and the "home!" of "Harvest-home!" in verse 4.',
        'bass' => 'Sings the bass line of Elvey\'s harmony, most often on G, often walking by step, as down D, C, B, A, G under "God, our Maker, doth provide" and "There for ever purified,", and rises to a G-sharp on the "Come" that opens the seventh line of each verse.',
    ],
    'now-thank-we-all-our-god' => [
        'soprano' => 'Carries Crüger\'s tune, mostly by step and on repeated notes, most often on C, up to its top D on "all our", "things hath", "on" and the start of "countless" in verse 1, and on "bounteous", the "joyful" of "ever-joyful", "when" and "free" in verse 2, and down to its low E only once a verse, on the start of "today." in verse 1 and on "the" in "In this world and the next." in verse 2.',
        'alto' => 'Sings the words a third or a sixth under the tune more than four fifths of the time, mostly a third, most often on A, high or low, up to its top B-flat on "all our" and "things hath" in verse 1 and "bounteous" and the "joyful" of "ever-joyful" in verse 2, and down to its low A on the long notes that end the second and fourth lines, and in the last line on "ours" and the end of "today." in verse 1 and on "and" and "next." in verse 2.',
        'tenor' => 'Sings the words in the middle of the chord, most often on C, then B-flat, with a G-sharp on "our" in "Hath blessed us on our way" and on the start of "perplexed,", up to its top D only on "Whom" in "In Whom His world rejoices;" and the start of "blessèd" in "And blessèd peace to cheer us;", and down to its low C only at the end of each verse, on "today." and on "the next.".',
        'bass' => 'Sings the bass line, most often on F, with an F-sharp under "countless" and "free us", up to its top B-flat only in the opening line, on "all our" in verse 1 and "bounteous" in verse 2, and down to its low F under the long notes that end the second and fourth lines, on the start of "mother\'s" in verse 1 and on "in" in "And keep us in His grace," in verse 2, and on the last word of each verse, "today." and "next.".',
    ],
    'we-gather-together' => [
        'soprano' => 'Carries the Netherlands tune, most often on A, up to its top E only on the end of "hastens" in verse 1 and of "maintaining" in verse 2, and down to its low D at the end of the first and third lines, on the first word of the last line ("Sing", "Thou,") and on its last two words ("his own.", "be thine!").',
        'alto' => 'Sings the words a third or a sixth under the tune three quarters of the time, mostly on D and F-sharp, up to G only on the end of "gather" in verse 1 and the first "us" in verse 2, down to A only on "Sing" and "Thou,", which open each verse\'s last line, and ends each verse a third above the tune, on F-sharp.',
        'tenor' => 'Sings the words in the middle of the chord, mostly on A, with a G-sharp in the second line, as on "make" and the start of "divine,", up to C-sharp only in the third line, on "The", "from" and the start of "distressing," in verse 1 and on "So" and "we were" in verse 2, and down to its low D only on the start of "praises" in verse 1 and on "Lord," in verse 2.',
        'bass' => 'Sings the bass line, on the roots three quarters of the time, most often on D, down to its low G only on "to" in "Sing praises to his name," and on "at" in "Thou, Lord, wast at our side,", and up to its top A in the first line on "Lord\'s" in verse 1 and "us" in verse 2, on the last word of the second line, "known;" and "divine,", and in the third line on "The", "from" and the start of "distressing," in verse 1 and on "So" and "we were" in verse 2.',
    ],
    'comin-thro-the-rye' => [
        'soprano' => 'Carries the tune, most often on its low D, where every "Gin a body" begins, and reaches its top E only where the third line runs into the fourth, on "I!" and "Yet" in verse 1 and on "I;" and "But" in verse 2.',
        'alto' => 'Sings the words a third or a sixth under the tune nearly nine tenths of the time, most often on its low B, never moving more than a third, up to its top B on "Nane," and "a\' the" in verse 1 and on "Ne\'er" and "a\' the" in verse 2.',
        'tenor' => 'Sings the words in the middle of the chord, mostly on G and A, with many repeated notes, up to its top D from the end of "laddie," through "Nane, they say, ha\'e" in verse 1 and "Ne\'er a ane ha\'e" in verse 2, and on every "a\' the", and down to its low D on the last word of the first, second and last lines of each verse: "rye,", "cry?" and "rye.", then "well,", "tell?" and "rye.".',
        'bass' => 'Sings the roots of the chords nearly nine tenths of the time, on just five notes, from G up to D, most often on its low G, which starts every line but the last in each verse.',
    ],
    'red-red-rose' => [
        'soprano' => 'Carries the tune, most often on C, then A and G, the widest of the four parts, from middle C, first on "love is" in "O, my love is like a red, red rose", up to its top G on "And" and "will" in the first "And I will love thee still," of verse 1 and the first "And I will come again," of verse 2.',
        'alto' => 'Sings the words a third or a sixth under the tune nearly four fifths of the time, most often on E, then F, rising to its top B at the end of a line, as on "June!" and "I;" in verse 1, and on the "And" that follows "I;" and "awhile!", and dipping to its low B, first on "like" in "O, my love is like".',
        'tenor' => 'Sings the words on C and G nine tenths of the time, mostly on C, holding one note for long stretches, up to D only on "I;" and "awhile!" and on the "And" that opens the first "And I will love thee still," and the first "And I will come again,", and down to F only twice, on "seas" and "thousand" later in those same two lines.',
        'bass' => 'Sings the bass line under Smith\'s chords, most often on C, with E, F and D where the chords turn, up to its top G only on "I;" in verse 1 and "awhile!" in verse 2, and then straight down an octave to its low G for the "And" that follows.',
    ],
    'annie-laurie' => [
        'soprano' => 'Carries Lady John Scott\'s tune, most often on C, high and low, down to middle C, as on the opening "Maxwelton" and "Her brow is" and every last "dee.", and up to its top E on "true," and "be;" in verse 1, on "on," and "e\'e" in verse 2, and on the "And" that opens each "And for bonnie Annie Laurie".',
        'alto' => 'Sings the words a third or a sixth under the tune three quarters of the time, most often on E, joins it on middle C at "Maxwelton", "there that", "Her brow is" and "face it", and steps a third above it, to E, where the tune falls to middle C on "true." in verse 1, "on," in verse 2 and every "lay" and "dee.", with its top C only on the "And" of each "And for bonnie Annie Laurie,".',
        'tenor' => 'Sings the words in the middle of the chord, mostly on G, with many repeated notes, up to C, as on the start of "Annie" in each "And for bonnie Annie Laurie", and down to its low E only on "Maxwelton" and "there that" in verse 1 and "Her brow is" and "face it" in verse 2.',
        'bass' => 'Sings the bass line, mostly on C, up to its top F only in the first half of each verse, on "bonnie, Where" and "Laurie," in verse 1 and "snaw drift, Her" and "fairest," in verse 2, and down to its low F, an octave under it, only on "Annie" in each "And for bonnie Annie Laurie,".',
    ],
    'will-ye-no-come-back-again' => [
        'soprano' => 'Carries the tune, most often on C, then F and A, up to its top F only on the "Will" that starts each chorus\'s second line, and down to middle C on "awa;" and "twa," in verse 1, on the opening "Ye" and on "men," and "glen," in verse 2, and on every "be" in "Better lo\'ed ye canna be".',
        'alto' => 'Sings the words a third or a sixth under the tune almost all the time, within one octave, from a low A to the A above it, and on one A or the other about half the time.',
        'tenor' => 'Sings the words in the middle of the chord, mostly on C and F, with many repeated notes, up to its top D only on "back" in the first "Will ye no come back again?" of each chorus, and down to its low C on the start of "Bonnie" and on "Mony" in verse 1, on "They kent" in verse 2 and on the last "again?" of each chorus.',
        'bass' => 'Sings the roots of the chords nearly nine tenths of the time, mostly on F, moving between the low F and the F an octave above it.',
    ],
    'ye-banks-and-braes' => [
        'soprano' => 'Carries the tune, slow and smooth, many of its words sung over two notes, most often on G, down to its low D, as on the first word of each verse, "Ye" and "Oft", and up to its top E only in the fifth and sixth lines: on "my", "warbling" and "flowering" in verse 1 and on "lightsome", "a" and "thorny" in verse 2.',
        'alto' => 'Sings the words close under the tune, mostly a third below it, on just six notes, from a low B up to G, most often on G, its top note.',
        'tenor' => 'Sings the words in the middle of the chord, mostly on D and G, with many repeated notes, and drops to its low D, an octave under its top note, only at the very end of each verse, on "turn." of "return." and on "me.".',
        'bass' => 'Sings the bass line, most often on B, then D and G, up to its top G on "bonie" in the first line of each verse, on the end of "departed" in "Thou minds me o\' departed joys," and on "staw my" in "And my fause luver staw my rose,".',
    ],
    'skye-boat-song' => [
        'soprano' => 'Carries the tune on just six notes, up to its top D only on "wing," and "king" in every chorus, and down to its low D only in the choruses, where every line begins and ends on it.',
        'alto' => 'Sings the words under the tune, mostly a sixth below it, often a third, most often on B, with many repeated notes, up to its top G only on "winds howl," in verse 1 and "waves leap," in verse 2, and down to its low G on the last word of every verse line: "air;" and "dare.", then "bed." and "head.".',
        'tenor' => 'Sings the words on just four notes, mostly on G, holding it through long stretches, up to C on "bird on the" and "born to be" in every chorus, and down to its low E only in the verses, as on "Thunderclaps" and "Flora will keep".',
        'bass' => 'Sings the bass line of Lawson\'s harmony, most often on a low G, the first and last note of every chorus line, and in the verses climbs B, D-sharp, E into the end of every line, reaching that top E also on "Loud the winds howl," and "Though the waves leap,".',
    ],
    'i-will-bow-and-be-simple' => [
        'soprano' => 'Carries the Shaker tune, most often on G, with many repeated notes, from middle C, only on the "I" that opens the first strain each time, up to its top E on the start of "humble," in the first strain, and in the second on "the" in "this is the token", on the end of "easy", and on "be broken, yea I\'ll", five notes in a row on the E.',
        'alto' => 'Sings the words a third or a sixth under the tune nine tenths of the time, mostly a third, most often on E, with many repeated notes, on just six notes, from middle C up to A: the A comes only in the first strain\'s second line, on "I" and "yea bow", and middle C only in its first line, on "I will", the end of "simple," and the "I" after it.',
        'tenor' => 'Sings the words in the middle of the chord, mostly on C, with many repeated notes, up to D only in the second strain, on the start of "token," and on "bow" in "I will bow and be broken,", and down to F only on "will" in "I will wear the easy yoke,".',
        'bass' => 'Holds the roots on "oo" more than nine tenths of the time, in long low notes, most often on C, starting the first strain on a C held for eight beats, and moving more often in the second strain.',
    ],
    'o-the-beautiful-treasure' => [
        'soprano' => 'Carries the minor-key tune, mostly by step, most often on G, then F-sharp and B, down to its low B only on "wise," in the first strain, and up to its top E only on the end of "bestow.", the last word of the second strain, each time.',
        'alto' => 'Sings the words a third or a sixth under the tune almost all the time, mostly a third, within one octave, from its low G on "O", "wise," and "prize." in the first strain up to its top G only in the second strain, on "than" and the end of "diamonds", and on "than", "can" and the end of "bestow.".',
        'tenor' => 'Sings the words in the middle of the chord, most often on G, up to its top C only once, on the start of "glorious" the second time through the first strain, and down to its low D on "How precious" each time and on the end of "glorious" the first time.',
        'bass' => 'Holds the roots on "oo" about four fifths of the time, in long low notes, most often on C, and goes down to its low G only in the second strain, where each line starts on it.',
    ],
    'who-will-bow-and-bend' => [
        'soprano' => 'Carries the tune, with many repeated notes, most often on E, down to middle C only in the first two strains: in the first on each "Who", on "In" and "From", and on the ends of "willow,", "freedom," and "blowing,", and in the second on "Pride" and the end of "working.", and up to its top E only in the second and third: on "of" and the start of "power,", on "bend to get", on the end of "turning," and the start of "twisting,", and on "starch".',
        'alto' => 'Sings the words a third or a sixth under the tune almost all the time, mostly a third, most often on E, with many repeated notes, up to its top B for most of "Dropping down like a shower," in the second strain and on "out all the" in the third, and down to its low A on each "Who" of the first strain, on "In" and "From the" and on the ends of "willow,", "freedom," and "blowing,", and in the second strain on "Pride and" and the end of "working.".',
        'tenor' => 'Sings the words in the middle of the chord, most often on G, then C, with many repeated notes, up to its top D on "Dropping down like a" and the start of "shower," in the second strain and on "Shake out all the" in the third, and down to its low C only on "bow" in "Who will bow and bend like a willow,".',
        'bass' => 'Holds the roots on "oo" nearly nine tenths of the time, in long low notes, most often on C, within one octave: down to its low F under the second "Who" of the first strain and under "reeling," in the third, and up to the F above it under the end of "freedom," and "From the" in the first strain, the end of "working." in the second, and "I will have" and the "I will" after it in the third.',
    ],
    'heavenly-treasures' => [
        'soprano' => 'Carries the lilting tune, mostly by step, most often on G, then B, and after each "treasures" and the last "praise" of each line carries the word through a run of wordless notes, reaching its low E only in those runs and its top E only on the first "Praise," of each line of the second strain.',
        'alto' => 'Sings the words mostly a third under the tune, a third or a sixth nearly nine tenths of the time, and "oo" under its wordless runs, most often on E and G, up to A only on the middle of "heavenly" each time, and down to its low G only on the last "oo" of the second strain, both times.',
        'tenor' => 'Sings on just four notes, from F-sharp up to B, most often on G, then B, singing "oo" under the tune\'s runs: its top B comes through "I am fill\'d with" and the start of "heavenly" each time, on "oo" in each run of the first strain, and on the "Praise, praise," that open the second strain\'s second line, and it drops to F-sharp only on the last "praise" of each line of the second strain.',
        'bass' => 'Holds a low E on "oo" for two thirds of the song, like a drone under the first strain, and in the second strain moves to the roots, E, G, C and D, under each "Praise, praise, praise, praise".',
    ],
    'las-mananitas' => [
        'soprano' => 'Carries the tune, mostly by step, most often on D, B and C, from its low D, only on the opening "Estas" of verse 1 and the start of "Amapolita" in verse 2, leaping up a sixth from there, to its top E: in each refrain on "pajarillos" and the start of "se escondió.", in verse 1 on the end of "David,", the "A las" after it and the end of "cantamos", and in verse 2 on the end of "Tepic,", the "Si no es" after it and the end of "Enamórate".',
        'alto' => 'Sings the words a third or a sixth under the tune more than four fifths of the time, mostly a third, most often on G, within one octave, from its low B, only on the opening "Estas" and the start of "Amapolita", up to its top B in every line: in verse 1 on the middle of "cantaba" and of "cantamos" and the start of "David," and "muchachas", in verse 2 on the start of "llanos" and "Tepic,", the end of "estás" and the middle of "Enamórate", and in each refrain on the start of the first "Despierta,", the middle of the second, the start of "Mira" and "cantan,", the end of "amaneció," and the "ya" of "La luna ya".',
        'tenor' => 'Sings the words on just five notes, from G up to D, most often on D, its top note, with many repeated notes, and down to its low G on "Estas son las" and the start of "mañanitas" that open verse 1, on "Amapolita" and the start of "morada" that open verse 2, and on the end of the last word of every verse and refrain: "aquí.", "mí." and "escondió.".',
        'bass' => 'Sings the roots of the chords most of the time, most often on its low G, and rises to its top G only in each refrain\'s first line, from the middle of the second "despierta," through the start of "Mira", and on the end of "amaneció,".',
    ],
    'riu-riu-chiu' => [
        'soprano' => 'Sings the opening call and both verses alone and the tune in every refrain, on just six notes, most often on B-flat, its top note, which begins every line, and down to its low D, a D natural, only on the end of "nuestra" and the start of "cordera" in each refrain\'s last line.',
        'alto' => 'Rests while the soprano sings the call and the verses, and in every refrain sings under the tune on just six notes, most often on E-flat, often a third below it, up to its top G-flat on the first "Riu" and, crossing above the tune, on "la" in "la guarda ribera" and at the end of both lines that end "cordera", and down to its low B-flat only on "de nuestra" in the refrain\'s last line.',
        'tenor' => 'Rests while the soprano sings the call and the verses, and in every refrain sings mostly on B-flat, with many repeated notes, up to its top D-flat on the first "Riu" and the start of the second, and on "Dios", the start of "guardó" and "el" in both "Dios guardó el lobo" lines, and down to its low E-flat only on the end of "guarda" and the start of "ribera", and on the middle of the last "cordera".',
        'bass' => 'Rests while the soprano sings the call and the verses, which the 1556 print gives to the bass, and in every refrain sings the print\'s bass, on the roots of the chords nearly nine tenths of the time, most often on E-flat, up to its top B-flat on "Dios", the start of "guardó" and "el" in both "Dios guardó el lobo" lines, and down to the B-flat an octave under it on the end of "chiu", the last two syllables of "ribera", the end of each "lobo", and the end of "nuestra" and the start of "cordera" in both lines that end "cordera".',
    ],
    'noche-de-paz' => [
        'soprano' => 'Carries the tune, most often on C and G, which take nearly half its time between them, up to its top F only on the first "estrella" in verse 1, the first "buen" in verse 2 and the first "eterno" in verse 3, and down to its low C only on the last note of each verse: "paz.", the end of "Redentor." and the end of "fulgor.".',
        'alto' => 'Sings the words a third or a sixth under the tune about three quarters of the time, mostly a third, most often on E, up to its top A once in each of the third and fourth lines of every verse, on "astros" and "anunciando", "celestes" and "glorias", "rostro" and "pesebre,", and down to its low B on "Todo", "En el" and "Ved qué" at the start of the second line, through "Brilla la estrella", "Por nuestro buen Re-" and "Astro de eterno" in the fifth line, and on the last "estrella", "buen" and "eterno", crossing above the tune only on the last two notes of each verse, "de paz.", the end of "Redentor." and "fulgor.".',
        'tenor' => 'Sings the words on just five notes, from E up to C, most often on G, with many repeated notes, up to its top C on "¡Noche de" at the start of each verse and on the three notes before the last note of the third and fourth lines, and down to its low E on the end of the second line, "derredor.", "al pastor," and "resplandor", and on the last word of the fifth line, "paz,", the end of "Redentor," and the end of "fulgor,".',
        'bass' => 'Hums the roots of the chords on "oo" in long held notes, mostly on C, up to its top F under the first half of the third and fourth lines of each verse, and down to its low G under the first half of the second and fifth lines, and for a moment under the last "estrella", "buen" and "eterno", before stepping up through B to each verse\'s closing C.',
    ],
    'pastores-a-belen' => [
        'soprano' => 'Carries the tune, most often on B and C, with many repeated notes, from its low D, only on the first notes of "Pastores" and "Vamos", leaping up a sixth from there, to its top E: on the middle of "María.", on the "llí, a-" that joins two "allí"s before "Nos espera Jesús," and again before "Nos convida su luz.", and on the start of "Niño" in the refrain\'s second "Llevemos" line.',
        'alto' => 'Sings the words a third or a sixth under the tune more than two thirds of the time, most often on F-sharp, with many repeated notes, within one octave, from its low B, only on the first notes of "Pastores" and "Vamos", up to its top B: on the end of "María." and the "A-" after it; on the start of the next "allí,", the end of the one after it and "Nos es-"; on the "A-" that opens "Allí, allí, Nos convida", the end of the second "allí," and "Nos"; and on "al" and the start of "Niño" in each of the refrain\'s last two lines.',
        'tenor' => 'Sings the words mostly on D, with many repeated notes, on just five notes, from G up to E, up to its top E only on the end of "turrones" in each "Llevemos" line, and down to its low G through "Pastores á Belén" and "Vamos con ale-", on the "-tro" of "nuestro", and on the end of the "Manuel" that closes each "Llevemos" line.',
        'bass' => 'Sings the roots of the chords more than nine tenths of the time, most often on its low G, then the D above it, with many repeated notes, beginning "Pastores", "Vamos", each run of "allí" calls, both "Llevemos" lines and both "al Niño Manuel" lines on that low G and ending every "Manuel" there, and rising to the G an octave above only on "Jesús," and "luz.", at the end of the two lines that begin "Nos".',
    ],
    'el-cant-dels-ocells' => [
        'soprano' => 'Sings the solo after the hummed opening, mostly by step, most often on C, from its low C, only on the first note of each verse, "Al" and "L\'A-", leaping up a fourth from there, to its top F only on "lo" and "va" at the start of the second line, and in the third line on "més" and the start of "ditxosa," in verse 1 and the start of "melodía," in verse 2.',
        'alto' => 'Hums "oo" under the soprano\'s solo, the top line of Millet\'s humming choir, mostly by step, most often on E-flat, often a sixth under the tune, up to its top E, an E natural, only under the end of "ditxosa," in verse 1 and of "melodía," in verse 2, and down to its low G only under "la nit" in verse 1 and the end of "cantant" with "ab" in verse 2.',
        'tenor' => 'Hums "oo" under the alto, most often on F, up to its top C only for a moment in the fourth line, under the end of "cantant" in each "los aucellets cantant" of verse 1 and under "nat" in each "dihent: Jesús es nat" of verse 2, and down to its low C only under the last note of "alegría.", the end of the song.',
        'bass' => 'Hums the bass line of Millet\'s harmony on "oo", most often on F, high or low. It holds its top F through the hummed opening and the first two lines of each verse, until the breath before the end of "lluminar" and "volant", and again in the bar between the verses; it goes down to the low F, an octave below, under the middle of every "los aucellets cantant" and "dihent: Jesús es nat", and under the end of every "melindrosa" and "alegría".',
    ],
];
